// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AutomationFigure) predicate.AutomationFigure {
	return predicate.AutomationFigure(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AutomationFigure) predicate.AutomationFigure {
	return predicate.AutomationFigure(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AutomationFigure) predicate.AutomationFigure {
	return predicate.AutomationFigure(sql.NotPredicates(p))
}
